def run(name: str, source: str) -> int:
    print(f"\n=== {name}")
    ns = {"__name__": "__main__", "__file__": str(ROOT / name)}
    try:
        exec(compile(source, name, "exec"), ns)
    except SystemExit as e:
        if isinstance(e.code, str):
            print(e.code)
            return 1
        return int(e.code or 0)
    return 0


def main() -> None:
    failed = [n for n, s in SCRIPTS.items() if run(n, s) != 0]
    print("\n=== Prüfung (admin.py doctor)")
    if (ROOT / "admin.py").exists():
        subprocess.run([sys.executable, str(ROOT / "admin.py"), "doctor"], cwd=ROOT)
    else:
        print("admin.py fehlt – bitte neben run.py kopieren")
    if failed:
        print("\nMit Fehlern: " + ", ".join(failed) + " – die Meldungen oben nennen die fehlenden Dateien/Stellen")
        sys.exit(1)
    print("\nFertig. Jetzt: systemctl restart vela  und im Browser Strg+F5")


if __name__ == "__main__":
    main()